// Keep only the frame items (the last item is the run summary) and number them.
const items = $input.all().map(i => i.json);
const summary = items.find(i => i.type === 'summary') || {};
const frames = items.filter(i => i.type !== 'summary' && i.imageUrl);
if (!frames.length) {
  throw new Error('Frameskim returned no frames. Check the video URL and the start/end range.');
}
return frames.map((f, idx) => ({
  json: {
    step: idx + 1,
    videoId: f.videoId || summary.videoId,
    videoTitle: summary.title || 'YouTube tutorial',
    t: f.t,
    ts: f.ts,
    imageUrl: f.imageUrl,
    text: (f.text || '').trim() || '(no narration in this segment)',
  },
}));

