// Pair each LLM answer with its segment, then build the Markdown guide.
const segments = $('Prepare steps from frames').all().map(i => i.json);
const answers = $input.all().map(i => i.json.text || '');

function parseStep(raw) {
  const cleaned = String(raw).replace(/```(?:json)?/g, '').trim();
  try {
    const obj = JSON.parse(cleaned);
    return { title: String(obj.title || '').trim(), instruction: String(obj.instruction || '').trim() };
  } catch (e) {
    return { title: '', instruction: cleaned };
  }
}

const first = segments[0];
const lines = [`# ${first.videoTitle}`, '', `Step-by-step guide generated from [the video](https://www.youtube.com/watch?v=${first.videoId}).`, ''];

segments.forEach((seg, i) => {
  const step = parseStep(answers[i] || '');
  const link = `https://www.youtube.com/watch?v=${seg.videoId}&t=${Math.floor(seg.t)}s`;
  lines.push(`## Step ${seg.step}: ${step.title || 'Step ' + seg.step}`, '');
  if (step.instruction) lines.push(step.instruction, '');
  lines.push(`![Step ${seg.step}](${seg.imageUrl})`, '');
  lines.push(`[Watch this part at ${seg.ts}](${link})`, '');
});

return [{ json: { title: first.videoTitle, videoId: first.videoId, steps: segments.length, markdown: lines.join('\n') } }];
